   INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
   ('00000000-0000-0000-0000-000000000000', 'Sind Projektphasen ein fester Bestandteil des Projektmanagements?', 2, '[{"text": "Ja", "correct": true, "because": "Strukturieren das Projekt"}, {"text": "Nein", "correct": false, "because": "Sie sind essenziell"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt Projektphasen?', 3, '[{"text": "Geordnete Abfolge", "correct": true, "because": "Phasen bauen aufeinander auf"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "Widerspricht Struktur"}, {"text": "Keine zeitliche Grenze", "correct": false, "because": "Phasen sind befristet"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Projektphasen teilen den Ablauf ein. b) Phasen sind immer gleich lang.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Länge variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören typischerweise zu einem Projekt?', 4, '[{"text": "Initiierung", "correct": true, "because": "Startphase"}, {"text": "Planung", "correct": true, "because": "Vorbereitungsphase"}, {"text": "Unendliche Wiederholung", "correct": false, "because": "Kein Projektmerkmal"}, {"text": "Abschluss", "correct": true, "because": "Endphase"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne definierte Phasen erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur ist nötig"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Phase kommt typischerweise zuerst?', 3, '[{"text": "Initiierung", "correct": true, "because": "Startet das Projekt"}, {"text": "Durchführung", "correct": false, "because": "Folgt später"}, {"text": "Abschluss", "correct": false, "because": "Letzte Phase"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Ist jede Projektphase gleich wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Gewichtung variiert je Projekt"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Relevanz"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört nicht zu den Projektphasen?', 3, '[{"text": "Dauerhafte Wartung", "correct": true, "because": "Kein Projekt, sondern Prozess"}, {"text": "Zieldefinition", "correct": false, "because": "Teil der Initiierung"}, {"text": "Ressourcenplanung", "correct": false, "because": "Teil der Planung"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Phasen haben Meilensteine. b) Phasen überschneiden sich nie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Überschneidung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Projektphasen?', 3, '[{"text": "Strukturieren den Ablauf", "correct": true, "because": "Geben Übersicht"}, {"text": "Verzögern das Projekt", "correct": false, "because": "Fördern Effizienz"}, {"text": "Erhöhen Kosten", "correct": false, "because": "Unabhängig davon"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Können Projektphasen je nach Methode variieren?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. agil vs. klassisch"}, {"text": "Nein", "correct": false, "because": "Anpassung ist üblich"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine typische Projektphase?', 3, '[{"text": "Planung der Ressourcen", "correct": true, "because": "Teil der Planungsphase"}, {"text": "Tägliche Routine", "correct": false, "because": "Kein Projektmerkmal"}, {"text": "Unendliche Forschung", "correct": false, "because": "Keine Phase"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Ist die Reihenfolge der Projektphasen immer starr?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibilität je Methode"}, {"text": "Ja", "correct": false, "because": "Variationen sind möglich"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Elemente definieren Projektphasen?', 4, '[{"text": "Ziele jeder Phase", "correct": true, "because": "Geben Richtung"}, {"text": "Zufällige Aufgaben", "correct": false, "because": "Fehlt Struktur"}, {"text": "Meilensteine", "correct": true, "because": "Markieren Fortschritt"}, {"text": "Zeitliche Begrenzung", "correct": true, "because": "Phasen sind befristet"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Müssen alle Projektphasen nacheinander ablaufen?', 2, '[{"text": "Nein", "correct": true, "because": "Parallele Phasen möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität erlaubt"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Phase schließt ein Projekt ab?', 3, '[{"text": "Abschluss", "correct": true, "because": "Beendet das Projekt"}, {"text": "Initiierung", "correct": false, "because": "Startet es"}, {"text": "Durchführung", "correct": false, "because": "Mittlere Phase"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Kann eine Projektphase übersprungen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Jede Phase hat Zweck"}, {"text": "Ja", "correct": false, "because": "Risiko für Fehler steigt"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Welche Methode beeinflusst die Projektphasen?', 3, '[{"text": "Agiles Vorgehen", "correct": true, "because": "Iterative Phasen"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Ordnung"}, {"text": "Zufällige Planung", "correct": false, "because": "Ungeeignet"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Phasen helfen bei der Kontrolle. b) Phasen sind nur für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, alle Projekte nutzen Phasen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
   ('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel von Projektphasen?', 3, '[{"text": "Übersichtlicher Ablauf", "correct": true, "because": "Fördert Struktur"}, {"text": "Maximale Verwirrung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Deadlines", "correct": false, "because": "Phasen sind befristet"}]');
